1	'use strict';
2	
3	/**
4	 * The strict zod schema for one slice spec file (specs/<entity>.json).
5	 *
6	 * A spec is pure data. Nothing in it may carry code, markup, a CSS value, or a
7	 * template string: every free-text string rejects the characters that could
8	 * open a tag, an interpolation, a template literal, or an escape sequence, and
9	 * every identifier is pinned by a regex. Unknown keys fail everywhere.
10	 *
11	 * `spec.schema.json` is generated from this file (see build-json-schema.cjs) and
12	 * a test fails when the two drift.
13	 */
14	
15	const { z } = require('zod');
16	
17	/** Characters a free-text string must never contain: < > { } backtick $ backslash, plus control characters. */
18	const FORBIDDEN_TEXT = /[<>{}`$\\\u0000-\u001f\u007f]/;
19	const SAFE_TEXT_PATTERN = '^[^<>{}`$\\\\\\u0000-\\u001f\\u007f]*$';
20	const SAFE_TEXT = new RegExp(SAFE_TEXT_PATTERN);
21	
22	/**
23	 * A free-text string: bounded length, none of the forbidden characters.
24	 * @param {number} max
25	 * @param {number} [min]
26	 */
27	const text = (max, min = 1) =>
28	  z
29	    .string()
30	    .min(min)
31	    .max(max)
32	    .regex(SAFE_TEXT, 'must not contain < > { } ` $ \\ or control characters');
33	
34	const ENTITY = /^[A-Z][a-z0-9]+([A-Z][a-z0-9]+)*$/;
35	const PLURAL = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;
36	const FIELD = /^[a-z][a-zA-Z0-9]*$/;
37	const ICON = /^lucide[A-Z][A-Za-z0-9]*$/;
38	const APP_PATH = /^\/[a-z0-9]+(-[a-z0-9]+)*(\/[a-z0-9]+(-[a-z0-9]+)*)*$/;
39	const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
40	const ID_STRING = /^[0-9]{1,6}$/;
41	
42	/** Field names that would collide with the generated `id` or with object internals. */
43	const RESERVED_FIELDS = new Set(['id', 'constructor', 'prototype', 'hasOwnProperty', 'toString', 'valueOf']);
44	
45	const entityName = z.string().max(40).regex(ENTITY, 'must be PascalCase, e.g. Mission or ThreatReport');
46	const pluralName = z.string().max(40).regex(PLURAL, 'must be lowercase kebab-case, e.g. missions or threat-reports');
47	const fieldName = z
48	  .string()
49	  .max(40)
50	  .regex(FIELD, 'must be camelCase')
51	  .refine((n) => !RESERVED_FIELDS.has(n), 'is reserved (id is generated, the rest collide with object internals)');
52	const iconName = z.string().max(60).regex(ICON, 'must look like lucideTarget');
53	const labelText = text(60);
54	const placeholderText = text(100);
55	const helpText = text(200);
56	const optionText = text(40);
57	const exampleText = text(500, 0);
58	const idString = z.string().regex(ID_STRING, 'must be a numeric id string such as "1"');
59	
60	const BADGE_VARIANTS = ['default', 'secondary', 'destructive', 'outline'];
61	const badgeVariant = z.enum(BADGE_VARIANTS);
62	
63	/** Properties every field carries. */
64	const base = {
65	  name: fieldName,
66	  label: labelText,
67	  required: z.boolean(),
68	  inForm: z.boolean().default(true),
69	  placeholder: placeholderText.optional(),
70	  help: helpText.optional(),
71	};
72	
73	const stringField = z.strictObject({ ...base, type: z.literal('string'), default: exampleText.optional() });
74	const textField = z.strictObject({ ...base, type: z.literal('text'), default: exampleText.optional() });
75	const numberField = z.strictObject({
76	  ...base,
77	  type: z.literal('number'),
78	  min: z.number().finite().optional(),
79	  max: z.number().finite().optional(),
80	  default: z.number().finite().optional(),
81	});
82	const booleanField = z.strictObject({ ...base, type: z.literal('boolean'), default: z.boolean().optional() });
83	const enumField = z.strictObject({
84	  ...base,
85	  type: z.literal('enum'),
86	  options: z.array(optionText).min(1).max(20),
87	  default: optionText.optional(),
88	});
89	const dateField = z.strictObject({
90	  ...base,
91	  type: z.literal('date'),
92	  default: z.string().regex(ISO_DATE, 'must be an ISO date, YYYY-MM-DD').optional(),
93	});
94	const refField = z.strictObject({
95	  ...base,
96	  type: z.literal('ref'),
97	  ref: z.strictObject({
98	    entity: entityName,
99	    plural: pluralName,
100	    label: fieldName,
101	  }),
102	  many: z.boolean().default(false),
103	  default: z.union([z.null(), z.array(idString).max(0)]).optional(),
104	});
105	
106	const field = z.discriminatedUnion('type', [
107	  stringField,
108	  textField,
109	  numberField,
110	  booleanField,
111	  enumField,
112	  dateField,
113	  refField,
114	]);
115	
116	const column = z.strictObject({
117	  field: fieldName,
118	  badge: z
119	    .strictObject({
120	      variants: z.record(optionText, badgeVariant),
121	      fallback: badgeVariant,
122	    })
123	    .optional(),
124	});
125	
126	const manage = z.strictObject({
127	  icon: iconName,
128	  createLabel: labelText,
129	  createRoute: z.string().max(60).regex(APP_PATH, 'must be an app path such as /recruit').optional(),
130	  columns: z.array(column).min(1).max(8),
131	  search: z.array(fieldName).min(1).max(4),
132	  filters: z
133	    .array(
134	      z.discriminatedUnion('control', [
135	        z.strictObject({ field: fieldName, control: z.literal('select') }),
136	        z.strictObject({
137	          field: fieldName,
138	          control: z.literal('toggle'),
139	          /** Required for an enum field: the single value the toggle filters to. */
140	          value: optionText.optional(),
141	          label: labelText,
142	          icon: iconName,
143	        }),
144	      ]),
145	    )
146	    .min(1)
147	    .max(3)
148	    .optional(),
149	  sort: z.strictObject({ field: fieldName, direction: z.enum(['asc', 'desc']) }).optional(),
150	  summary: z.boolean().optional(),
151	});
152	
153	const KINDS = ['entity', 'form', 'manage'];
154	
155	const specObject = z.strictObject({
156	  entity: entityName,
157	  plural: pluralName,
158	  labels: z.strictObject({ singular: labelText, plural: labelText }),
159	  kinds: z.array(z.enum(KINDS)).min(1).max(3),
160	  fields: z.array(field).min(1).max(24),
